@lru_cache(maxsize=1)
def decode_all_emotion_scanlines() -> dict[str, list[list[tuple[int, int, int, int]]]]:
    raw = lzma.decompress(base64.b85decode(SOA_LZMA_B85.encode("ascii")))
    n = TOTAL_SPANS
    dys = raw[0:n]
    x0s = raw[n : 2 * n]
    ws = raw[2 * n : 3 * n]
    cs = raw[3 * n : 4 * n]
    out: dict[str, list[list[tuple[int, int, int, int]]]] = {}
    cursor = 0
    for emo, counts in EMOTION_SPAN_COUNTS.items():
        emo_frames: list[list[tuple[int, int, int, int]]] = []
        for cnt in counts:
            y = 0
            spans: list[tuple[int, int, int, int]] = []
            end = cursor + cnt
            while cursor < end:
                y += dys[cursor]
                spans.append((y, x0s[cursor], ws[cursor], cs[cursor]))
                cursor += 1
            emo_frames.append(spans)
        out[emo] = emo_frames
    return out


def main() -> int:
    ap = argparse.ArgumentParser(
        description="Decode and inspect the 21 canonical Mochi scanline vector animations (240x147, 8-color)."
    )
    ap.add_argument("--emotion", type=str, default=None, help="Filter summary to a single emotion")
    ap.add_argument("--json", action="store_true", help="Emit JSON summary")
    args = ap.parse_args()
    decoded = decode_all_emotion_scanlines()
    if args.emotion:
        frames = decoded.get(args.emotion, [])
        summary = {args.emotion: [len(f) for f in frames]}
    else:
        summary = {k: sum(len(f) for f in v) for k, v in decoded.items()}
    if args.json:
        print(json.dumps(summary, indent=2))
    else:
        for k, v in summary.items():
            print(f"{k:13s}: {v}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

